#[path = "solution.rs"]
mod solution;

use solution::{parse_profile_card, ProfileCard};

#[test]
fn parses_required_fields_in_any_order_with_ascii_whitespace() {
    let input = "\tcategory = tools \r\nsummary= compact card\n code = X-1 \nlabel = Example\t\n";
    assert_eq!(parse_profile_card(input).unwrap(), ProfileCard {
        code: "X-1".to_string(),
        label: "Example".to_string(),
        summary: "compact card".to_string(),
        category: "tools".to_string(),
    });
}

#[test]
fn required_values_may_be_empty_and_blank_lines_are_ignored() {
    let input = "\ncode=\n\nlabel=\nsummary=\ncategory=\n";
    assert_eq!(parse_profile_card(input).unwrap(), ProfileCard {
        code: String::new(),
        label: String::new(),
        summary: String::new(),
        category: String::new(),
    });
}

#[test]
fn unknown_fields_are_ignored_but_do_not_hide_required_fields() {
    let input = "future=literal value\ncode=c\nlabel=l\nsummary=s\ncategory=k\nother=42\n";
    let card = parse_profile_card(input).unwrap();
    assert_eq!(card.code, "c");
    assert_eq!(card.label, "l");
    assert_eq!(card.summary, "s");
    assert_eq!(card.category, "k");
}

#[test]
fn empty_blank_and_missing_required_documents_are_invalid() {
    for input in [
        "",
        "\n \t\n",
        "code=c\nlabel=l\nsummary=s\n",
        "unknown=value\n",
    ] {
        assert!(parse_profile_card(input).is_err(), "unexpectedly accepted {input:?}");
    }
}

#[test]
fn rejects_malformed_lines_and_empty_keys() {
    let suffix = "\ncode=c\nlabel=l\nsummary=s\ncategory=k\n";
    for bad_line in ["no separator", "=value", "key=a=b"] {
        let input = format!("{bad_line}{suffix}");
        assert!(parse_profile_card(&input).is_err());
    }
}

#[test]
fn rejects_duplicate_required_and_duplicate_unknown_keys() {
    let duplicate_required = "code=a\ncode=b\nlabel=l\nsummary=s\ncategory=c\n";
    assert!(parse_profile_card(duplicate_required).is_err());

    let duplicate_unknown = "extra=1\ncode=a\nlabel=l\nextra=2\nsummary=s\ncategory=c\n";
    assert!(parse_profile_card(duplicate_unknown).is_err());
}

#[test]
fn values_are_literal_after_trimming_and_result_owns_text() {
    let mut input = String::from("code=$HOME\nlabel={name}\nsummary=hello world\ncategory=x\n");
    let card = parse_profile_card(&input).unwrap();
    input.clear();
    assert_eq!(card.code, "$HOME");
    assert_eq!(card.label, "{name}");
    assert_eq!(card.summary, "hello world");
    assert_eq!(card.category, "x");
}

